// Source of truth: pair-setup.mts. The sibling .mjs is generated by `yarn workspace @ask-llm/mcp build:hooks`; never edit it.
// Question-free marker setup for /codex-pair: copy a committed template and keep the marker out of git
// through the repository's local exclude file. An existing marker is never overwritten.
import { execFileSync } from "node:child_process";
import { appendFileSync, copyFileSync, constants, lstatSync, mkdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { CONTEXT_FILENAME, PAIR_ROOT_DIR } from "./state.mjs";
export const TEMPLATE_DIR = ".codex-pair.example";
const EXCLUDE_LINE = `${PAIR_ROOT_DIR}/`;
function git(cwd, args) {
    return execFileSync("git", ["-C", cwd, ...args], {
        encoding: "utf8",
        stdio: ["ignore", "pipe", "pipe"],
        timeout: 5000,
    }).trim();
}
function exists(path) {
    try {
        lstatSync(path);
        return true;
    }
    catch {
        return false;
    }
}
// A linked worktree's .git is a file, so ask git where the exclude file lives instead of joining paths.
export function excludeFilePath(root) {
    return resolve(root, git(root, ["rev-parse", "--git-path", "info/exclude"]));
}
function ignoredByGit(root, marker) {
    try {
        git(root, ["check-ignore", "-q", marker]);
        return true;
    }
    catch (err) {
        // Exit 1 means "not ignored"; anything else is a real git failure.
        if (err.status === 1)
            return false;
        throw err;
    }
}
export function ensureExcluded(root, marker) {
    try {
        if (ignoredByGit(root, marker))
            return { kind: "already-ignored" };
        const excludeFile = excludeFilePath(root);
        let current = "";
        try {
            current = readFileSync(excludeFile, "utf8");
        }
        catch {
            mkdirSync(dirname(excludeFile), { recursive: true });
        }
        const separator = current.length > 0 && !current.endsWith("\n") ? "\n" : "";
        appendFileSync(excludeFile, `${separator}${EXCLUDE_LINE}\n`);
        return { kind: "excluded", excludeFile };
    }
    catch (err) {
        return { kind: "failed", reason: err?.message ?? String(err) };
    }
}
export function setupMarker(cwd) {
    let root;
    try {
        root = git(cwd, ["rev-parse", "--show-toplevel"]);
    }
    catch (err) {
        return { kind: "not-git", reason: err?.message ?? String(err) };
    }
    const marker = join(root, PAIR_ROOT_DIR, CONTEXT_FILENAME);
    const template = join(root, TEMPLATE_DIR, CONTEXT_FILENAME);
    if (exists(marker))
        return { kind: "exists", root, marker, ignore: ensureExcluded(root, marker) };
    if (!exists(template))
        return { kind: "no-template", root, marker, template };
    // A symlinked template could pull a file from outside the repository into the reviewer's context.
    if (!lstatSync(template).isFile())
        return { kind: "invalid-template", root, template };
    mkdirSync(dirname(marker), { recursive: true });
    try {
        copyFileSync(template, marker, constants.COPYFILE_EXCL);
    }
    catch (err) {
        if (err?.code !== "EEXIST")
            throw err;
        return { kind: "exists", root, marker, ignore: ensureExcluded(root, marker) };
    }
    return { kind: "created", root, marker, template, ignore: ensureExcluded(root, marker) };
}
function describeIgnore(ignore) {
    if (ignore.kind === "excluded")
        return `codex-pair: ${PAIR_ROOT_DIR}/ is ignored through ${ignore.excludeFile}`;
    if (ignore.kind === "already-ignored")
        return `codex-pair: ${PAIR_ROOT_DIR}/ is already ignored by git`;
    return `codex-pair: could not add ${PAIR_ROOT_DIR}/ to git's local exclude file: ${ignore.reason}`;
}
export function setupFailed(outcome) {
    if (outcome.kind === "invalid-template")
        return true;
    return (outcome.kind === "created" || outcome.kind === "exists") && outcome.ignore.kind === "failed";
}
// The first word of the first line is the outcome the skill branches on.
export function formatSetup(outcome) {
    switch (outcome.kind) {
        case "not-git":
            return "not-git: not inside a git repository; draft the marker interactively. Nothing is added to git ignore rules.";
        case "no-template":
            return [
                `no-template: ${outcome.template} does not exist; draft the marker interactively and write it to ${outcome.marker}.`,
                `Then run setup again to keep ${PAIR_ROOT_DIR}/ out of git.`,
            ].join("\n");
        case "invalid-template":
            return `invalid-template: ${outcome.template} is not a regular file; nothing was copied.`;
        case "created":
            return [`created: copied ${outcome.template} to ${outcome.marker}`, describeIgnore(outcome.ignore)].join("\n");
        case "exists":
            return [`exists: ${outcome.marker} already exists and was left unchanged`, describeIgnore(outcome.ignore)].join("\n");
    }
}
